update public.fields set verification_status='verified_against_standard', verification_quote='Suma de las emisiones de gases de efecto invernadero (GEI) (3.1.2.5) y remociones de GEI (3.1.2.6) en un sistema producto (3.1.3.2), expresadas como $\mathrm{CO}_{2}$ equivalente (3.1.2.2) y basadas en una evaluación del ciclo de vida (3.1.4.3) utilizando la categoría de impacto (3.1.4.8) única de cambio climático. | La unidad declarada sólo se debe utilizar en una HCP parcial. — printed pp.14, 28', verification_note='md-verified 2026-09-05 (§3.1.1.1 / §3.1.1.2 / §6.3.3, printed pp.14, 28) [VC] — Enum {hcp, hcp_parcial} = die beiden gedruckten Studientypen; die Auswahl steuert funktionelle vs. deklarierte Einheit (6.3.3).', verified_at=now() where id='d17747e6-7c10-4dc0-bd5f-d785a5169381' and verification_status not in ('verified_against_standard','corrected');
