update public.fields set verification_status='verified_against_standard', verification_quote='Si existe más de un conjunto de RCP o HCP-RCP pertinente, la organización que aplica este documento debe revisar el RCP o HCP-RCP pertinente (por ejemplo, para los límites del sistema, la modularidad, la asignación, la calidad de los datos). La elección del RCP o HCP-RCP adoptado debe estar justificada. — printed p.26', verification_note='md-verified 2026-09-05 (§6.2, printed p.26) [VC] — Gedruckt ist die Begruendungspflicht HART ("debe estar justificada"), aber an rcp_pcr_used=true gebunden; im Encoding is_required=false und kein Gate - siehe STAGED S-2.', verified_at=now() where id='f6683964-4c85-4a9a-b2c9-86275bbf4faf' and verification_status not in ('verified_against_standard','corrected');
