-- life_cycle_perspective  (§5.2)
update public.fields set verification_status='verified_against_standard', verification_quote='La cuantificación de una HCP toma en consideración todo el ciclo de vida de un producto, incluida la adquisición de materia prima, el diseño, la producción, el transporte/entrega, el uso y el tratamiento al final de la vida útil. — printed p.24', verification_note='md-verified 2026-09-05 (§5.2, printed p.24) [VC] — Kapitel 5 sind PRINZIPIEN, im Indikativ gedruckt ("toma en consideración"), nicht "se debe" - kein Muss-Satz.', verified_at=now() where id='88d0e621-d3f7-4f31-99ec-0532923485b1' and verification_status not in ('verified_against_standard','corrected');
