-- scientific_priority  (§5.5)
update public.fields set verification_status='verified_against_standard', verification_quote='La preferencia a las ciencias naturales (tales como física, química, biología) se da al tomar decisiones en el estudio de HCP. | Sólo si no existe ni una base científica natural ni una justificación basada en otros enfoques científicos o en convenciones internacionales es posible tomar decisiones basadas en juicios de valor. — printed p.24', verification_note='md-verified 2026-09-05 (§5.5, printed p.24) [VC] — Prinzip (Indikativ), kein Muss-Satz.', verified_at=now() where id='a7e936fb-02fc-460b-985f-5029f2d97481' and verification_status not in ('verified_against_standard','corrected');
-- completeness_principle  (§5.7)
