-- functional_unit  (§6.3.3)
update public.fields set verification_status='verified_against_standard', verification_quote='Un estudio de HCP debe especificar claramente la unidad funcional o declarada del sistema en estudio. La unidad funcional o declarada debe ser coherente con el objetivo y alcance del estudio de la HCP. El propósito principal de una unidad funcional o declarada es proporcionar una referencia a la cual las entradas y salidas están relacionadas. Por lo tanto, la unidad funcional o declarada debe estar claramente definida y ser medible. — printed p.28', verification_note='md-verified 2026-09-05 (§6.3.3, printed p.28) [VC] — Gedruckt ist eine ODER-Pflicht ("unidad funcional o declarada"); im Encoding ist functional_unit is_required=true UNBEDINGT und declared_unit=false - ODER-Kollaps, siehe STAGED S-3.', verified_at=now() where id='ba9aab71-fb05-4a1a-b16a-554370857de6' and verification_status not in ('verified_against_standard','corrected');
