-- excluded_stages_justification  (§6.3.4.1)
update public.fields set verification_status='verified_against_standard', verification_quote='La exclusión de etapas, procesos, entradas o productos del ciclo de vida, dentro del sistema en estudio, sólo está permitida si no cambian significativamente las conclusiones generales del estudio de la HCP. Cualquier decisión de excluir etapas del ciclo de vida, procesos, entradas o salidas se deben declarar y se deben explicar los motivos y las implicaciones para su exclusión. — printed p.29', verification_note='md-verified 2026-09-05 (§6.3.4.1, printed p.29) [VC]', verified_at=now() where id='b0a1c10c-816c-4830-9085-fb4d8acf17ab' and verification_status not in ('verified_against_standard','corrected');
-- cutoff_criteria  (§6.3.4.3)
update public.fields set verification_status='verified_against_standard', verification_quote='Se deben definir criterios de corte coherentes que permitan la exclusión de ciertos procesos de menor importancia dentro de la fase de definición de objetivos y alcance. | El efecto de los criterios de corte seleccionados sobre el resultado del estudio también se debe evaluar y describir en el informe de estudio de la HCP (véanse 6.4.5 y 6.6). — printed pp.29-30', verification_note='md-verified 2026-09-05 (§6.3.4.3, printed pp.29-30) [VC] — Gate ISO-14067-CR-06 zitiert stattdessen den Einschluss-Satz "En general, se deben incluir todos los procesos..." - der traegt die Abschneidekriterien-Pflicht nicht; siehe STAGED S-4.', verified_at=now() where id='29d96c8c-0bbb-4fab-a9b9-8e23b64bbab4' and verification_status not in ('verified_against_standard','corrected');
-- data_type_hierarchy  (§6.3.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Se deben recopilar datos específicos del lugar para los procesos individuales en los que la organización que lleva a cabo el estudio de la HCP tenga control financiero u operacional y sean representativos de los procesos para los que se recogen. También deben utilizarse datos específicos del sitio para aquellos procesos unitarios que son más importantes y no están bajo control financiero u operacional. | Los datos secundarios sólo se deben utilizar para entradas y productos en los que no sea factible la recopilación de datos primarios o para procesos de menor importancia. — printed p.30', verification_note='md-verified 2026-09-05 (§6.3.5, printed p.30) [VC] — Gedruckt ist eine PRIORITAETSREGEL; das Gate ISO-14067-CR-07 prueft nur die Zugehoerigkeit zur vollstaendigen Enum-Liste und erzwingt die Regel nicht - siehe STAGED S-5.', verified_at=now() where id='505debb2-6dee-4d0b-834a-74e88e8e0321' and verification_status not in ('verified_against_standard','corrected');
