update public.fields set verification_status='verified_against_standard', verification_quote='La calidad de los datos se debe caracterizar por aspectos cuantitativos y cualitativos. La caracterización de la calidad de los datos debería abordar lo siguiente: | a) cobertura relacionada con el tiempo: edad de los datos y el período mínimo de tiempo durante el cual los datos deberían recopilarse; — printed p.30', verification_note='md-verified 2026-09-05 (§6.3.5, printed p.30) [VC] — ACHTUNG: die Dachpflicht ist hart ("se debe caracterizar"), die Liste a)-j) aber WEICH ("debería abordar"). Das Feldlabel "(a-j)" liest die Liste als Pflicht - siehe STAGED S-6.', verified_at=now() where id='f2c96c47-691d-4590-a104-23f2ca55ad3d' and verification_status not in ('verified_against_standard','corrected');
-- data_quality_two_stage  (§6.3.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Para la evaluación de la calidad de los datos se debe adoptar un enfoque en dos etapas: | los requisitos de calidad de los datos de conformidad con los puntos a) a d) anteriores se deben caracterizar por el estudio de la HCP; | los datos se deben evaluar con respecto a los requisitos con los puntos a) a d) anteriores. — printed p.30', verification_note='md-verified 2026-09-05 (§6.3.5, printed p.30) [VC] — Harte Pflicht, aber KEIN Gate erzwingt sie - siehe STAGED S-11.', verified_at=now() where id='df4dd90e-65f2-4e28-a21e-c58c2f15323f' and verification_status not in ('verified_against_standard','corrected');
-- time_boundary_period  (§6.3.6)
update public.fields set verification_status='verified_against_standard', verification_quote='El límite de tiempo para los datos es el período de tiempo para el cual la cifra cuantificada para la HCP es representativa. | Se debe especificar y justificar el período de tiempo durante el cual la HCP es representativa. — printed p.31', verification_note='md-verified 2026-09-05 (§6.3.6, printed p.31) [VC]', verified_at=now() where id='3f62ebfe-32ef-496a-8af2-2e8b3f6643ee' and verification_status not in ('verified_against_standard','corrected');
-- use_stage_included  (§6.3.7)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando se incluya la etapa de uso en el ámbito del estudio de la HCP (véase 6.3.2), se deben incluir las emisiones y remociones de GEI derivadas de la etapa de uso del producto. — printed p.32', verification_note='md-verified 2026-09-05 (§6.3.7, printed p.32) [VC]', verified_at=now() where id='218bfc20-a4f1-4c12-8d1b-b6c2eaef12e3' and verification_status not in ('verified_against_standard','corrected');
-- use_profile  (§6.3.7)
update public.fields set verification_status='verified_against_standard', verification_quote='El usuario del producto y el perfil de uso en que se utilice el producto se deben especificar en el estudio de la HCP. | Cuando no se justifique de otro modo, la determinación del perfil de uso (es decir, los escenarios relacionados, la vida útil y el mercado seleccionado) se debe basar en información técnica publicada, por ejemplo: — printed p.32', verification_note='md-verified 2026-09-05 (§6.3.7, printed p.32) [VC] — Harte Pflicht unter dem Geltungsvorbehalt use_stage_included=true; im Encoding is_required=false ohne Praedikat - siehe STAGED S-7.', verified_at=now() where id='69290ec7-72d8-4280-8c58-861942b0def4' and verification_status not in ('verified_against_standard','corrected');
-- service_life  (§6.3.7)
update public.fields set verification_status='verified_against_standard', verification_quote='La información de vida útil debe ser verificable y se debe referir a las condiciones de uso previstas ya las funciones relacionadas del producto. — printed p.32', verification_note='md-verified 2026-09-05 (§6.3.7, printed p.32) [VC] — Der Drucksatzfehler "previstas ya las" (statt "previstas y a las") ist verbatim wiedergegeben. Feld hat unit="-": die Norm nennt keine Einheit fuer die Nutzungsdauer.', verified_at=now() where id='b8ab16cf-d36d-4a54-a6cf-0c0b239e694b' and verification_status not in ('verified_against_standard','corrected');
-- eol_stage_included  (§6.3.8)
update public.fields set verification_status='verified_against_standard', verification_quote='Todas las emisiones y remociones de GEI derivadas de la fase de fin de vida de un producto se deben incluir en un estudio de HCP, si esta etapa se incluye en el alcance (véase 6.3.2). — printed p.33', verification_note='md-verified 2026-09-05 (§6.3.8, printed p.33) [VC]', verified_at=now() where id='21eea4f4-0702-43ba-9710-74d04223ebe2' and verification_status not in ('verified_against_standard','corrected');
-- eol_scenario  (§6.3.8)
update public.fields set verification_status='verified_against_standard', verification_quote='Todos los supuestos pertinentes relativos al tratamiento al final de su vida útil deben: | Los escenarios de fin de vida deben reflejar el mercado actual y ser representativos de una de las alternativas más probables o se puede evaluar más de un escenario (incluyendo escenarios futuros). — printed p.33', verification_note='md-verified 2026-09-05 (§6.3.8, printed p.33) [VC] — Harte Pflicht unter dem Geltungsvorbehalt eol_stage_included=true; im Encoding is_required=false ohne Praedikat - siehe STAGED S-7.', verified_at=now() where id='1d37619d-7345-4440-aeb5-853793f787c0' and verification_status not in ('verified_against_standard','corrected');
-- data_collection_complete  (§6.4.2)
update public.fields set verification_status='verified_against_standard', verification_quote='Los datos cualitativos y cuantitativos para su inclusión en el inventario del ciclo de vida se deben recopilar para todos los procesos unitarios incluidos en el sistema en estudio. | Los procesos unitarios significativos se deben documentar en el informe del estudio de la HCP. — printed p.34', verification_note='md-verified 2026-09-05 (§6.4.2, printed p.34) [VC]', verified_at=now() where id='66840a39-ef80-4798-9e97-0cd21a26ede6' and verification_status not in ('verified_against_standard','corrected');
-- data_validation_done  (§6.4.3)
update public.fields set verification_status='verified_against_standard', verification_quote='Durante el proceso de recopilación de datos se debe realizar un control de la validez de los datos para confirmar y proporcionar evidencias de que se han cumplido los requisitos de calidad de los datos especificados en el apartado 6.3.5. | La validación debería incluir el establecimiento de balances de masa, balances energéticos y/o análisis comparativos de factores de emisión u otros métodos apropiados. — printed p.35', verification_note='md-verified 2026-09-05 (§6.4.3, printed p.35) [VC]', verified_at=now() where id='8f01c0e9-187f-420d-9492-9d6fece60367' and verification_status not in ('verified_against_standard','corrected');
-- data_related_to_reference_flow  (§6.4.4)
update public.fields set verification_status='verified_against_standard', verification_quote='Se debe determinar un flujo apropiado para cada proceso unitario. Los datos cuantitativos de entrada y salida del proceso unitario se deben calcular en relación con este flujo. | El cálculo debe relacionar los datos de entrada y salida del sistema con la unidad funcional o declarada. — printed p.35', verification_note='md-verified 2026-09-05 (§6.4.4, printed p.35) [VC]', verified_at=now() where id='8a65913b-a883-4400-99a3-e7d1b9675a36' and verification_status not in ('verified_against_standard','corrected');
-- allocation_procedure  (§6.4.6.2)
update public.fields set verification_status='verified_against_standard', verification_quote='El estudio de la HCP debe incluir la identificación de los procesos compartidos con otros sistemas producto y debe tratar con ellos de acuerdo con el procedimiento por pasos que se presenta a continuación. | a) Paso 1: Siempre que sea posible se debería evitar la asignación | b) Paso 2: Cuando no se pueda evitar la asignación, las entradas y salidas del sistema deberían dividirse entre sus diferentes productos o funciones de manera que reflejen las relaciones físicas subyacentes entre ellos. — printed p.36', verification_note='md-verified 2026-09-05 (§6.4.6.2, printed p.36) [VC] — Die Dachpflicht ist hart, die drei Schritte selbst sind WEICH gedruckt ("se debería evitar", "deberían dividirse"). Kein Gate erzwingt das Feld - siehe STAGED S-11.', verified_at=now() where id='c9a8f300-1066-4e98-83c2-18a7a7c5b2f3' and verification_status not in ('verified_against_standard','corrected');
-- allocation_mass_balance  (§6.4.6.1)
update public.fields set verification_status='verified_against_standard', verification_quote='La suma de las entradas y salidas asignadas de un proceso unitario debe ser igual a las entradas y salidas del proceso unitario antes de la asignación. — printed p.36', verification_note='md-verified 2026-09-05 (§6.4.6.1, printed p.36) [VC] — Dies ist der Satz, der die Massenbilanz fordert; Gate ISO-14067-CR-13 zitiert stattdessen den Zuordnungsverfahrens-Satz - siehe STAGED S-8.', verified_at=now() where id='013a15ad-07f2-47bc-9b24-9e1b9a532a53' and verification_status not in ('verified_against_standard','corrected');
-- performance_tracking  (§6.4.7)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando se pretenda utilizar la HCP para el seguimiento del desempeño, los siguientes requisitos adicionales para la cuantificación de la HCPse deben cumplir: | El período de tiempo entre los puntos en el tiempo para el cual se lleva a cabo el seguimiento del desempeño de la HCP no debe ser más corto que el límite de tiempo para los datos como se describe en el apartado 6.3.6. — printed p.38', verification_note='md-verified 2026-09-05 (§6.4.7, printed p.38) [VC] — Der Drucksatzfehler "la HCPse deben cumplir" ist verbatim wiedergegeben.', verified_at=now() where id='bcb7e688-2244-4356-b134-b62ad065b346' and verification_status not in ('verified_against_standard','corrected');
-- timing_emissions_over_10y  (§6.4.8)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando las emisiones y remociones de GEI derivadas de la etapa de uso (véase 6.3.7) y/o de la etapa de fin de vida (véase 6.3.8) se produzcan durante más de diez años (si no se especifica de otro modo en la RCP pertinente) después de que el producto ha sido puesto en uso, el tiempo de las emisiones y remociones de GEI en relación con el año de producción del producto se debe especificar en el inventario de ciclo de vida. — printed p.38', verification_note='md-verified 2026-09-05 (§6.4.8, printed p.38) [VC] — Die 10-Jahres-Grenze ist gedruckt "durante más de diez años" (STRIKT groesser). Sie ist im Encoding als Boolean gefuehrt, es gibt kein numerisches Feld und damit keine Grenzwert-Inklusivitaet im Encoding.', verified_at=now() where id='6827e822-1fc4-475e-a2a3-ea646eeff71b' and verification_status not in ('verified_against_standard','corrected');
-- fossil_ghg_net  (§6.4.9.2)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones y remociones de GEI de los fósiles se deben incluir en la HCP o HCP parcial y se deben documentar por separado como resultado neto. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.2, printed pp.38-44) [VC]', verified_at=now() where id='6e850f60-5fdf-47ac-a176-2d970fd56c51' and verification_status not in ('verified_against_standard','corrected');
-- biogenic_ghg  (§6.4.9.2)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones y remociones biogénicas de GEI se deben incluir en la HCP o en la HCP parcial y deberían expresarse por separado (véase la figura 3). — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.2, printed pp.38-44) [VC]', verified_at=now() where id='d42f83b5-b48d-4a70-a2ae-fdced2b7eae1' and verification_status not in ('verified_against_standard','corrected');
-- biogenic_carbon_content  (§6.4.9.3)
update public.fields set verification_status='verified_against_standard', verification_quote='Si se calcula el contenido de carbono biogénico de un producto, se debe documentar por separado en el informe del estudio de la HCP, pero no se debe incluir en el resultado de la HCP o de la HCP parcial. | Se debe proporcionar información sobre el contenido de carbono biogénico al realizar estudios de la cuna a la puerta, ya que esta información puede ser pertinente para la cadena de valor restante. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.3, printed pp.38-44) [VC] — Einheit kg (Kohlenstoffmasse), NICHT kg CO2e - konsistent damit, dass der Wert ausdruecklich NICHT in das HCP-Ergebnis eingeht.', verified_at=now() where id='085127e9-c804-4074-bb4a-8bd783aa9f1c' and verification_status not in ('verified_against_standard','corrected');
-- electricity_treatment  (§6.4.9.4)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones de GEI asociadas con el uso de electricidad deben incluir: | Cuando la electricidad se genera internamente (por ejemplo, electricidad generada en el sitio) y se consume para un producto en estudio y no se han vendido instrumentos contractuales a un tercero, los datos del ciclo de vida de esa electricidad se deben utilizar para ese producto. | Cuando no se disponga de información sobre la electricidad específica del proveedor, se deben utilizar las emisiones de GEI asociadas a la red eléctrica pertinente de la cual se obtiene la electricidad. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.4, printed pp.38-44) [VC] — Die vier Enum-Werte spiegeln 6.4.9.4.2 / 6.4.9.4.3 / 6.4.9.4.4 (lieferantenspezifisch bzw. Netz). Feld is_required=false, Gate CR-17 aber block - Widerspruch, siehe STAGED S-10.', verified_at=now() where id='afd2a2ae-f19d-444d-96d7-694baddf593c' and verification_status not in ('verified_against_standard','corrected');
-- luc_direct_ghg  (§6.4.9.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones y remociones de GEI que ocurren como resultado del cambio directo de uso del suelo (CUS) en las últimas décadas (véase la NOTA 1) se deben evaluar de acuerdo con métodos internacionalmente reconocidos, como las Directrices del IPCC para los Inventarios Nacionales de Gases de Efecto Invernadero ${ }^{[17]}$ e incluido en la HCP. | Las emisiones y remociones netas de GEI, CUS se deben documentar por separado en el informe del estudio de la HCP. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.5, printed pp.38-44) [VC] — Gedruckt HART ("se deben evaluar ... e incluido en la HCP"); Encoding: is_required=false und Gate CR-18 nur warn - Unter-Erzwingung, siehe STAGED S-10.', verified_at=now() where id='43e4fd27-b63f-4af9-8160-61ad5ae99ccb' and verification_status not in ('verified_against_standard','corrected');
-- luc_indirect_considered  (§6.4.9.5)
update public.fields set verification_status='verified_against_standard', verification_quote='Se debería incluir el cambio del uso del suelo indirecto (CUSi) en los estudios de la HCP una vez que exista un procedimiento acordado internacionalmente. | Todas las opciones y supuestos, incluidas las metodologías aplicadas, se deben justificar y documentar en el informe de estudio de la HCP. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.5, printed pp.38-44) [VC] — WEICH gedruckt ("se debería"), is_required=false und kein Gate - konsistent.', verified_at=now() where id='856f5660-315e-4801-834f-83913482b0e7' and verification_status not in ('verified_against_standard','corrected');
-- land_use_ghg  (§6.4.9.6)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones y remociones de GEI que ocurren como resultado del uso del suelo a través de cambios en las reservas de carbono del suelo y la biomasa que no son el resultado de cambios en el uso del suelo se deberían evaluar e incluir en la HCP. Si no se evalúan los cambios en las reservas de carbono del suelo y de la biomasa, esta decisión se debe justificar en el informe del estudio de la HCP. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.6, printed pp.38-44) [VC] — WEICH gedruckt ("se deberían evaluar e incluir"), aber die Begruendung bei Nichtbewertung ist HART.', verified_at=now() where id='09926923-0436-4c76-b9dc-2a5e70208deb' and verification_status not in ('verified_against_standard','corrected');
-- aircraft_ghg  (§6.4.9.7)
update public.fields set verification_status='verified_against_standard', verification_quote='Las emisiones de GEI del transporte aéreo se deben incluir en la HCP y se deben documentar por separado en el informe del estudio de la HCP. | Cuando se utilice un multiplicador de la aviación, el efecto de este multiplicador no se debe incluir en la HCP y se debe notificar por separado junto con la fuente. — printed pp.38-44', verification_note='md-verified 2026-09-05 (§6.4.9.7, printed pp.38-44) [VC] — Gedruckt HART; Encoding: is_required=false und Gate CR-19 nur warn - Unter-Erzwingung, siehe STAGED S-10.', verified_at=now() where id='87cce471-9dc0-4cf2-909b-f8760772a940' and verification_status not in ('verified_against_standard','corrected');
-- E_V  (Anexo D, §D.3 (Fórmula D.1))
update public.fields set verification_status='verified_against_standard', verification_quote='Para la asignación de ciclo cerrado, cada emisión de GEI vinculada a las operaciones de adquisición de materia prima y final de su vida útil se puede calcular de acuerdo con la fórmula (D.1): | son las emisiones ligadas a la extracción o producción de las materias primas necesarias para el producto, provenientes de recursos naturales, como si fueran todos materiales primarios; — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.3 (Fórmula D.1), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='abda35f9-a2e1-426b-b3bf-a04a6878a32f' and verification_status not in ('verified_against_standard','corrected');
-- E_EoL  (Anexo D, §D.3 (Fórmula D.1))
update public.fields set verification_status='verified_against_standard', verification_quote='Para la asignación de ciclo cerrado, cada emisión de GEI vinculada a las operaciones de adquisición de materia prima y final de su vida útil se puede calcular de acuerdo con la fórmula (D.1): | son las emisiones ligadas a las operaciones de fin de vida (que son parte del sistema producto el cual entrega el material reciclado); — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.3 (Fórmula D.1), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='d87c9fa9-1105-4acd-bb34-4db66ccc54c5' and verification_status not in ('verified_against_standard','corrected');
-- R  (Anexo D, §D.3 (Fórmula D.1))
update public.fields set verification_status='verified_against_standard', verification_quote='Para la asignación de ciclo cerrado, cada emisión de GEI vinculada a las operaciones de adquisición de materia prima y final de su vida útil se puede calcular de acuerdo con la fórmula (D.1): | es el índice de reciclado del material; | es el crédito de reciclado. — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.3 (Fórmula D.1), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Dimensionslos (unit="-"), da R als Quote in R*E_V auftritt.', verified_at=now() where id='0d5b6655-6fee-49ab-a5ad-1889b2699d94' and verification_status not in ('verified_against_standard','corrected');
-- E_M  (Anexo D, §D.3 (Fórmula D.1))
update public.fields set verification_status='verified_against_standard', verification_quote='Para la asignación de ciclo cerrado, cada emisión de GEI vinculada a las operaciones de adquisición de materia prima y final de su vida útil se puede calcular de acuerdo con la fórmula (D.1): | E_{\mathrm{M}}=E_{\mathrm{V}}+E_{\mathrm{EoL}}-R \cdot E_{\mathrm{V}} \tag{D.1} | son las emisiones de GEI ligadas a la adquisición de materias primas y operaciones de fin de vida; — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.3 (Fórmula D.1), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='9df3ef67-f91d-4b00-b94e-a5fcebef280b' and verification_status not in ('verified_against_standard','corrected');
-- A  (Anexo D, §D.4)
update public.fields set verification_status='verified_against_standard', verification_quote='incluye la elección de un factor de asignación, A, que se determina como la relación entre el precio de mercado del material de desecho o el material reciclado y el mercado global del precio del material primario, generalmente como un promedio durante un período de tiempo más largo, por ejemplo cinco años. | Si el material reciclado tiene el mismo valor de mercado que el material primario, entonces se obtiene un factor de asignación $A=1$, incluso si las propiedades inherentes difieren de las del material primario. Si el material reciclado se entrega de forma gratuita, entonces el factor de asignación $A=0$. — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4, printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. A=1 und A=0 sind gedruckte Endpunkte, KEIN gedruckter Wertebereich zur Auswahl; A=0,5 nennt die Norm ausdruecklich als in der Literatur vorgeschlagenen willkuerlichen Faktor, nicht als Norm-Wert (SR-2: nichts vorbelegen).', verified_at=now() where id='51ca6f75-3245-4a0b-9000-fd5f0ffc3448' and verification_status not in ('verified_against_standard','corrected');
-- C  (Anexo D, §D.4)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto consiste tanto de material primario y reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materia prima y las operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.5) o fórmula (D.6): | donde $C$ es el contenido reciclado del producto. — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4, printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='a7b96010-4f61-4cea-84e9-5e8a17a05ab0' and verification_status not in ('verified_against_standard','corrected');
-- E_PP  (Anexo D, §D.4)
update public.fields set verification_status='verified_against_standard', verification_quote='donde $E_{\mathrm{PP}}$ son las emisiones de GEI ligadas al pre-procesamiento de material reciclado para cumplir los requisitos de calidad del material primario sustituido. — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4, printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='41a53794-d939-4dcc-8c52-7af5d6182199' and verification_status not in ('verified_against_standard','corrected');
-- E_M_D2  (Anexo D, §D.4 (Fórmula D.2))
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material primario, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materias primas y operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.2): | E_{\mathrm{M}}=E_{\mathrm{V}}+E_{\mathrm{EoL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.2} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.2), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich.', verified_at=now() where id='6c79cb8d-f0bb-4b31-a8f0-a4123efec794' and verification_status not in ('verified_against_standard','corrected');
-- E_M_D3  (Anexo D, §D.4 (Fórmula D.3))
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con las operaciones de adquisición de materias primas y final de su vida útil se pueden calcular de acuerdo con la fórmula (D.3) o la fórmula (D.4): | E_{\mathrm{M}}=E_{\mathrm{V}} \cdot A+E_{\mathrm{PP}}+E_{\mathrm{EoL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.3} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.3), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. D.3 und D.4 sind gedruckte ALTERNATIVEN fuer denselben Fall und algebraisch identisch.', verified_at=now() where id='bf089da0-788d-418b-9159-eb7f9a418128' and verification_status not in ('verified_against_standard','corrected');
-- E_M_D4  (Anexo D, §D.4 (Fórmula D.4))
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con las operaciones de adquisición de materias primas y final de su vida útil se pueden calcular de acuerdo con la fórmula (D.3) o la fórmula (D.4): | E_{\mathrm{M}}=E_{\mathrm{PP}}+E_{\mathrm{EoL}}+(1-R) \cdot A \cdot E_{\mathrm{V}} \tag{D.4} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.4), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. D.4 ist die gedruckte Alternative zu D.3 fuer denselben Fall und algebraisch identisch.', verified_at=now() where id='ad5e4ce5-7694-4d32-a96b-f74b1f3640f3' and verification_status not in ('verified_against_standard','corrected');
-- E_M_D5  (Anexo D, §D.4 (Fórmula D.5))
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto consiste tanto de material primario y reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materia prima y las operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.5) o fórmula (D.6): | E_{\mathrm{M}}=C \cdot A \cdot E_{\mathrm{V}}+C \cdot E_{\mathrm{PP}}+(1-C) \cdot E_{\mathrm{V}}+E_{\mathrm{EOL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.5} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.5), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. D.5 und D.6 sind gedruckte ALTERNATIVEN fuer denselben Fall und algebraisch identisch.', verified_at=now() where id='d6eefbe4-217d-41b2-94b7-a8dbbd1418ef' and verification_status not in ('verified_against_standard','corrected');
-- E_M_D6  (Anexo D, §D.4 (Fórmula D.6))
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando un producto consiste tanto de material primario y reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materia prima y las operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.5) o fórmula (D.6): | E_{\mathrm{M}}=C \cdot E_{\mathrm{PP}}+(1-C) \cdot E_{\mathrm{V}}+E_{\mathrm{EoL}}+(C-R) \cdot A \cdot E_{\mathrm{V}} \tag{D.6} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.6), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. D.6 ist die gedruckte Alternative zu D.5 fuer denselben Fall und algebraisch identisch.', verified_at=now() where id='9b96f76f-8231-4b6b-9a72-a9336b98cee3' and verification_status not in ('verified_against_standard','corrected');
-- ghg_mass  (§6.5.1)
update public.fields set verification_status='verified_against_standard', verification_quote='En la fase AICV de un estudio HCP, el impacto potencial del cambio climático de cada GEI emitido y eliminado por el sistema producto se debe calcular multiplicando la masa de GEI liberada o eliminada por el PCG a 100 años proporcionado por el IPCC en unidades de kg CO2e por kg de emisión (con retroalimentación de carbono, según IPCC). — printed p.45', verification_note='md-verified 2026-09-05 (§6.5.1, printed p.45) [VC] — Einheit kg; multipliziert mit gwp_100 (kg CO2e/kg) ergibt kg CO2e - dimensionsrichtig.', verified_at=now() where id='b46c9e2b-ecfa-463d-9acd-ea2b31ac089d' and verification_status not in ('verified_against_standard','corrected');
-- gwp_100  (§6.5.1)
update public.fields set verification_status='verified_against_standard', verification_quote='En la fase AICV de un estudio HCP, el impacto potencial del cambio climático de cada GEI emitido y eliminado por el sistema producto se debe calcular multiplicando la masa de GEI liberada o eliminada por el PCG a 100 años proporcionado por el IPCC en unidades de kg CO2e por kg de emisión (con retroalimentación de carbono, según IPCC). | Cuando los valores de PCG sean modificados por el IPCC, se deben utilizar los últimos valores en los cálculos de HCP si no se indica y justifica de otro modo. — printed p.45', verification_note='md-verified 2026-09-05 (§6.5.1, printed p.45) [VC] — Die Zahlenwerte selbst stehen NICHT in dieser Norm - sie verweist auf den IPCC-Bericht (NR aus diesem Dokument).', verified_at=now() where id='94e18815-59d1-4a2d-9299-c8c4f17f5532' and verification_status not in ('verified_against_standard','corrected');
-- cfp_result  (§6.5.1 / §7.2)
