-- biogenic_co2_characterization  (§6.5.2)
update public.fields set verification_status='verified_against_standard', verification_quote='Las remociones de $\mathrm{CO}_{2}$ en biomasa se deben caracterizar en la AICV como -1 kg de $\mathrm{CO}_{2} \mathrm{e} / \mathrm{kg}$ de $\mathrm{CO}_{2}$ en el cálculo de la HCP al ingresar al sistema producto. | Las emisiones de $\mathrm{CO}_{2}$ biogénico se deben caracterizar como $+1 \mathrm{~kg} \mathrm{CO}_{2} \mathrm{e} / \mathrm{kg} \mathrm{CO}_{2}$ de carbono biogénico en el cálculo de la HCP. | Para el metano fósil y biogénico, se deben utilizar los factores de caracterización de acuerdo con el informe más reciente del IPCC. — printed p.45', verification_note='md-verified 2026-09-05 (§6.5.2, printed p.45) [VC] — SR-1: die beiden Werte -1 und +1 kg CO2e/kg CO2 sind in dieser Sitzung verbatim aus dem Transkript gelesen. Es sind FESTWERTE, kein Bereich.', verified_at=now() where id='648db44d-8bbb-42f0-b962-5f61e8cb19db' and verification_status not in ('verified_against_standard','corrected');
