-- systematic_cfp_approach  (Anexo C (normativ))
update public.fields set verification_status='verified_against_standard', verification_quote='Si una organización decide desarrollar un enfoque sistemático de HCP debe cumplir con los requisitos que figuran en este anexo. | La organización debe describir su enfoque sistemático de la HCP, incluida la secuencia e interacción de las actividades que forman parte de este proceso, y establecer procedimientos para garantizar que la operación, el control y el seguimiento del enfoque sistemático de la HCP son efectivos. — printed p.52', verification_note='md-verified 2026-09-05 (Anexo C (normativ), printed p.52) [VC]', verified_at=now() where id='5d23d399-f3d9-480e-a7a1-ce4b169b6cd0' and verification_status not in ('verified_against_standard','corrected');
-- critical_review  (§8)
