-- EQ-03  (Anexo D, §D.4 (Fórmula D.2))
update public.equations set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material primario, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materias primas y operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.2): | E_{\mathrm{M}}=E_{\mathrm{V}}+E_{\mathrm{EoL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.2} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.2), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Fall: Produkt zu 100 % Primaermaterial. Dimensionspruefung: alle Terme kg CO2e, R und A dimensionslos.', verified_at=now() where id='450ece72-5b56-48d0-90c6-75e19d0ae0f6' and verification_status <> 'verified_against_standard';
-- EQ-04  (Anexo D, §D.4 (Fórmula D.3))
update public.equations set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con las operaciones de adquisición de materias primas y final de su vida útil se pueden calcular de acuerdo con la fórmula (D.3) o la fórmula (D.4): | E_{\mathrm{M}}=E_{\mathrm{V}} \cdot A+E_{\mathrm{PP}}+E_{\mathrm{EoL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.3} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.3), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Fall: Produkt zu 100 % Recyclingmaterial. D.3 und D.4 sind gedruckte Alternativen ("o") fuer DENSELBEN Fall und algebraisch identisch - kein Szenario-Unterscheidungsmerkmal im Encoding, siehe STAGED S-13.', verified_at=now() where id='8195c5e7-6782-4a4d-9821-1b711385a9bc' and verification_status <> 'verified_against_standard';
-- EQ-05  (Anexo D, §D.4 (Fórmula D.4))
update public.equations set verification_status='verified_against_standard', verification_quote='Cuando un producto se compone al $100 \%$ de material reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con las operaciones de adquisición de materias primas y final de su vida útil se pueden calcular de acuerdo con la fórmula (D.3) o la fórmula (D.4): | E_{\mathrm{M}}=E_{\mathrm{PP}}+E_{\mathrm{EoL}}+(1-R) \cdot A \cdot E_{\mathrm{V}} \tag{D.4} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.4), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Fall: Produkt zu 100 % Recyclingmaterial, gedruckte Alternative zu D.3 und algebraisch identisch - siehe STAGED S-13.', verified_at=now() where id='a07bd085-706c-4641-a6fb-85611d98ae1f' and verification_status <> 'verified_against_standard';
-- EQ-06  (Anexo D, §D.4 (Fórmula D.5))
update public.equations set verification_status='verified_against_standard', verification_quote='Cuando un producto consiste tanto de material primario y reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materia prima y las operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.5) o fórmula (D.6): | E_{\mathrm{M}}=C \cdot A \cdot E_{\mathrm{V}}+C \cdot E_{\mathrm{PP}}+(1-C) \cdot E_{\mathrm{V}}+E_{\mathrm{EOL}}-R \cdot A \cdot E_{\mathrm{V}} \tag{D.5} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.5), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Fall: Produkt aus Primaer- UND Recyclingmaterial. D.5 und D.6 sind gedruckte Alternativen und algebraisch identisch - siehe STAGED S-13.', verified_at=now() where id='f369ed15-f791-4753-9d08-053806b55289' and verification_status <> 'verified_against_standard';
-- EQ-07  (Anexo D, §D.4 (Fórmula D.6))
update public.equations set verification_status='verified_against_standard', verification_quote='Cuando un producto consiste tanto de material primario y reciclado, entonces, en el caso de reciclado de ciclo abierto, las emisiones de GEI relacionadas con la adquisición de materia prima y las operaciones al final de su vida útil se pueden calcular de acuerdo con la fórmula (D.5) o fórmula (D.6): | E_{\mathrm{M}}=C \cdot E_{\mathrm{PP}}+(1-C) \cdot E_{\mathrm{V}}+E_{\mathrm{EoL}}+(C-R) \cdot A \cdot E_{\mathrm{V}} \tag{D.6} — printed pp.54-58', verification_note='md-verified 2026-09-05 (Anexo D, §D.4 (Fórmula D.6), printed pp.54-58) [VC] — Anexo D ist INFORMATIV. Die Formel ist in diesem Dokument abgedruckt, die Verifikation ist daher gegen den eigenen Text dieser Norm; die Bindung bleibt unverbindlich. Fall: Produkt aus Primaer- UND Recyclingmaterial, gedruckte Alternative zu D.5 und algebraisch identisch - siehe STAGED S-13.', verified_at=now() where id='59c28418-d4a8-4ff5-bbfb-6029cb6c7024' and verification_status <> 'verified_against_standard';
